def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally overall and recent behavior.
    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for me, op in history:
        if me == 'C':
            my_c += 1
        if op == 'C':
            opp_c += 1
        if me == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    my_d = n - my_c
    last_me, last_op = history[-1]

    # Consecutive streaks at the tail.
    opp_c_streak = 0
    opp_d_streak = 0
    for _, op in reversed(history):
        if op == 'D':
            if opp_c_streak:
                break
            opp_d_streak += 1
        else:
            if opp_d_streak:
                break
            opp_c_streak += 1

    def opp_change_count():
        c = 0
        prev = history[0][1]
        for i in range(1, n):
            cur = history[i][1]
            if cur != prev:
                c += 1
            prev = cur
        return c

    # Early-game: establish cooperation, retaliate immediately on defection.
    if n < 6:
        if n == 1:
            return 'C'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Hardcore defector: minimize losses.
    if opp_d * 4 >= n * 3:
        return 'D'

    # Pure cooperator: exploit, but re-cooperate if they punish (they don't
    # really punish, but hedge against conditional players).
    if opp_d == 0:
        if n >= 92:
            return 'D'
        # Defect most of the time while preserving occasional C.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    recent_len = 10 if n >= 10 else n
    recent = history[-recent_len:]
    r_opp_d = 0
    r_my_d = 0
    for me, op in recent:
        if op == 'D':
            r_opp_d += 1
        if me == 'D':
            r_my_d += 1

    # If we are both stuck in mostly-defect mode, try a single olive branch
    # after sustained mutual defection to unlock cooperation.
    if r_opp_d >= 4 and r_my_d >= 4:
        if last_op == 'D' and last_me == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        if last_op == 'C':
            return 'C'
        return 'D'

    # Mostly-defecting opponent: defect with rare probes to test for change.
    if r_opp_d * 2 >= recent_len:
        if last_op == 'C':
            return 'C'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # Opponent largely cooperative recently.
    if r_opp_d <= 1:
        if last_op == 'D':
            # Punish a defection, but be forgiving if it was isolated.
            if opp_c_streak >= 3:
                return 'C'
            if opp_d_streak == 1 and rng.random() < 0.7:
                return 'D'
            if opp_d_streak >= 2:
                return 'D'
            return 'D'
        # Exploit gently when the opponent is reliably cooperative.
        if n > 25 and r_my_d * 3 < my_c:
            if rng.random() < 0.18:
                return 'D'
            return 'C'
        return 'C'

    # Moderate opponent defection rate. Use forgiving tit-for-tat with
    # occasional exploitation when cooperation has been stable.
    if last_op == 'D':
        if opp_d_streak >= 2:
            return 'D'
        # Single defection: retaliate but soften if overall cooperative.
        if opp_c * 5 >= n * 3:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'

    # Opponent last cooperated.
    if opp_c * 3 >= n * 2:
        # Cooperative frame: reward with C, exploit rarely.
        if n >= 30 and r_opp_d == 0 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Cautious frame.
    if rng.random() < 0.75:
        return 'C'
    return 'D'
